import React,{useEffect,useMemo,useState}from'react';
import{createRoot}from'react-dom/client';
import{Activity,Workflow,ScanLine,BrainCircuit,Layers3,ArrowRight,UploadCloud,Play,RefreshCw,RotateCcw,Database,Settings2,TrendingUp,FileText,CheckCircle2,AlertTriangle,Gauge,Network,Search,History,ExternalLink,Sparkles,LineChart as LineIcon,ShieldCheck,Factory,GitBranch,Box,Eye,Download,BookOpen,Code2,Cloud,Server,HardDrive,Milestone,Braces,Info,ChevronDown}from'lucide-react';
import{BarChart,Bar,XAxis,YAxis,Tooltip,ResponsiveContainer,CartesianGrid,LineChart,Line,ReferenceLine}from'recharts';
import'./style.css';


class AppErrorBoundary extends React.Component{
  constructor(props){super(props);this.state={error:null}}
  static getDerivedStateFromError(error){return {error}}
  componentDidCatch(error,info){console.error("Workbench UI error:",error,info)}
  render(){
    if(this.state.error){
      return <div style={{padding:40,color:'#eaf2fa',background:'#081321',minHeight:'100vh',fontFamily:'Arial'}}>
        <h2>AI Operations Workbench could not render</h2>
        <p style={{color:'#9fb2c6'}}>A frontend error occurred. Copy the message below and send it for troubleshooting.</p>
        <pre style={{whiteSpace:'pre-wrap',background:'#101d2d',padding:18,borderRadius:10,color:'#ffb8c0'}}>{String(this.state.error)}</pre>
      </div>
    }
    return this.props.children
  }
}

const nav=[['Overview',Layers3],['Compressor Health',Activity],['Feed Optimizer',Workflow],['Visual Inspection',ScanLine],['Technology Intelligence',BrainCircuit]];
const moduleMeta={
 'Compressor Health':{tag:'PREDICT',subtitle:'Detect emerging compressor degradation before it becomes an operational event.',icon:Activity},
 'Feed Optimizer':{tag:'OPTIMIZE',subtitle:'Allocate available gas through constrained processing routes to maximize planning value.',icon:Workflow},
 'Visual Inspection':{tag:'SEE',subtitle:'Turn equipment photographs into structured information for digital operator rounds.',icon:ScanLine},
 'Technology Intelligence':{tag:'UNDERSTAND',subtitle:'Continuously research meaningful technology deployments and convert them into decision-ready intelligence.',icon:BrainCircuit}
};

const API_BASES={
  compressor:(import.meta.env.VITE_COMPRESSOR_API_BASE||'/api/compressor').replace(/\/$/,''),
  optimizer:(import.meta.env.VITE_OPTIMIZER_API_BASE||'/api/optimizer').replace(/\/$/,''),
  vision:(import.meta.env.VITE_VISION_API_BASE||'/api/vision').replace(/\/$/,''),
  intelligence:(import.meta.env.VITE_INTELLIGENCE_API_BASE||'/api/intelligence').replace(/\/$/,'')
};
const api=(service,path='')=>`${API_BASES[service]}${path}`;

const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v||0);
const fmt=v=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(v??0);

function Flow({steps}){return <div className="flow">{steps.map((s,i)=><React.Fragment key={s.title}><div className="flowNode"><span>{s.kicker}</span><b>{s.title}</b><small>{s.text}</small></div>{i<steps.length-1&&<div className="flowArrow"><ArrowRight size={18}/></div>}</React.Fragment>)}</div>}
function PageIntro({name,children}){let m=moduleMeta[name];let Icon=m.icon;return <><div className="pageKicker"><span>{m.tag}</span><span>APPLICATION</span></div><div className="pageTitleRow"><div><h1>{name}</h1><p className="lead">{m.subtitle}</p></div><div className="heroIcon"><Icon size={34}/></div></div><ModuleKnowledge name={name}/>{children}</>}
function ProblemCard({problem,decision,output}){return <div className="problemGrid"><div><span>BUSINESS PROBLEM</span><p>{problem}</p></div><div><span>DECISION</span><p>{decision}</p></div><div><span>OUTPUT</span><p>{output}</p></div></div>}
function EmptyState({title,text}){return <div className="empty"><Box size={22}/><b>{title}</b><span>{text}</span></div>}


const moduleDocs={
'Compressor Health':{
 deep:{summary:'An unsupervised anomaly-detection pipeline for multivariable compressor surveillance. The model learns the envelope of normal behavior from historical operating data and scores new observations by how unusual they are.',facts:[['Data','Hourly timestamped process and condition-monitoring tags'],['Preparation','Cleaning → feature engineering → StandardScaler using training baseline'],['Engine','scikit-learn Isolation Forest'],['Model output','Row-level anomaly score + 24-hour rolling signal'],['Decision logic','Attention and High thresholds convert a score into an operational status'],['Serving','FastAPI POST /compressor/analyze'],['Frontend','React upload, status card and trend visualization'],['Artifacts','compressor_scaler.pkl + compressor_isolation_forest.pkl + threshold configuration']],details:['Training and inference are deliberately separated: the scaler and Isolation Forest are fit only on the training baseline and are reused for later data.','Features such as pressure ratio, temperature rise and normalized power help the model see relationships rather than only raw tags.','Isolation Forest is appropriate for this learning use case because failure labels are not required; unusual combinations are isolated more quickly than normal operating patterns.','The health signal is an anomaly indicator, not a diagnosis. Engineering context is still required before acting.']},
 build:[['1 · Data prototype','Created six months of synthetic compressor data and a known degradation pattern for learning and validation.'],['2 · Notebook model','Explored features, split training/test periods, fit StandardScaler and Isolation Forest, inspected anomaly scores and thresholds.'],['3 · Saved inference artifacts','Persisted the trained scaler/model as .pkl files so the application does not retrain for every request.'],['4 · Backend service','Wrapped preprocessing and inference in FastAPI and defined a CSV upload contract.'],['5 · Application','Built the user workflow: upload → analyze → health status → trend → interpretation.'],['6 · Product frontend','Moved from Streamlit prototype to a React experience while retaining the Python AI backend.']],
 cloud:[['Local prototype','Browser → localhost React/Streamlit → FastAPI :8001 → local model files. Everything runs on the laptop.'],['Container-ready','Frontend and compressor service receive their own Docker images with pinned dependencies and repeatable startup commands.'],['Azure application','Frontend is exposed through HTTPS. The FastAPI compressor service can run privately in Azure Container Apps/App Service and is called through internal routing.'],['Production hardening','Model artifacts move to controlled storage/versioning; logs and metrics go to Azure Monitor; secrets/configuration are injected through environment settings/Key Vault; authentication and network controls can be added.']],
 architecture:[['User / Browser','Uploads compressor CSV and reviews health decision'],['React Frontend','Validates user interaction, calls /api/compressor and renders charts'],['API Routing','Public-facing path maps to the compressor FastAPI service'],['FastAPI Application','Parses the file, validates schema and orchestrates preprocessing + inference'],['Preprocessing','Derived features + saved StandardScaler transform'],['ML Model','Saved Isolation Forest scores every row'],['Decision Layer','Rolling score + thresholds → Normal / Attention / High'],['Response','JSON → React status cards and trend chart']],
 dataapi:{input:'CSV: timestamp plus required operating tags such as pressure, temperature, flow, speed/vibration depending on the model schema.',endpoint:'POST /compressor/analyze (proxied by the frontend as /api/compressor/compressor/analyze)',response:'rows_analyzed, current_anomaly_score, attention_threshold, high_threshold, status and timestamped trend.',storage:'Model and scaler are currently local serialized artifacts; no operational historian is connected in the portfolio build.'},
 validation:{works:['End-to-end inference path is implemented from file upload through model scoring to UI.','Synthetic degradation data allows the anomaly response to be visually checked.','Training transformations are reused at inference rather than being refit on uploaded data.'],limits:['Synthetic data is not evidence of field accuracy.','Isolation Forest flags abnormality but does not identify root cause or remaining useful life.','Real deployment would require tag mapping, missing-data handling, model monitoring and validation against maintenance/inspection history.'],next:['Connect to a historian/PI-style source instead of file upload.','Add explainability/contribution views and asset-specific baselines.','Add model registry, drift monitoring and retraining governance.']}
},
'Feed Optimizer':{
 deep:{summary:'A constrained operations-research model that decides how much feed should flow through allowable plant and fractionator routes to maximize product value while respecting physical capacities and feed availability.',facts:[['Data','Feed availability/composition, plant capacities, fractionator capacities/recoveries, route permissions, product prices'],['Decision variables','Continuous flow on every allowed Feed → Plant → Fractionator route'],['Engine','SciPy linear programming (linprog)'],['Objective','Maximize estimated daily value of residue gas + recovered NGL products'],['Constraints','Feed availability, plant capacity, fractionator capacity and allowed connectivity'],['Serving','FastAPI POST /optimizer/run'],['Frontend','Scenario inputs, editable assumptions, run action, economic and utilization results'],['Outputs','Recommended route flows, feed use/curtailment, plant/fractionator loading and economic uplift']],details:['Each route receives an economic coefficient derived from feed composition, product values and component recovery assumptions.','The optimizer does not “predict” the answer; it mathematically searches the feasible region for the best objective value.','The model is intentionally linear for transparency and speed. A real plant could require nonlinear yields, pressure constraints, compressor power, quality limits, hydraulics and integer operating decisions.','The baseline vs optimized comparison is illustrative because the portfolio economics are synthetic.']},
 build:[['1 · Business formulation','Translated the planning question into decision variables, objective function and constraints.'],['2 · Input workbook','Structured feeds, compositions, capacities, recoveries, route matrix and prices in an Excel/CSV-friendly format.'],['3 · Notebook optimization','Built and debugged the route economics and linear program; checked feed, plant and fractionator balances.'],['4 · Reusable optimizer','Moved model logic into optimizer.py so it could run outside the notebook.'],['5 · FastAPI service','Exposed the optimization as an API instead of tying it directly to a UI.'],['6 · Product workflow','Added scenario editing/upload, conceptual process scheme, decision output and constraint/utilization views.']],
 cloud:[['Local prototype','React/Streamlit UI → localhost FastAPI :8002 → SciPy optimizer + local input assumptions.'],['Container-ready','Optimizer service becomes a self-contained Python container; frontend calls it by service URL rather than localhost.'],['Azure application','React frontend is public; optimizer API is an internal Azure service. Scenario files can be stored in Blob Storage and run metadata/results in PostgreSQL/Azure SQL.'],['Production hardening','Identity, audit trail, scenario versioning, solver timeout controls, monitoring and integration to planning/data platforms are added.']],
 architecture:[['Planner / User','Selects sample scenario, edits assumptions or uploads workbook'],['React Frontend','Presents process scheme, tables and scenario controls'],['FastAPI Application','Validates request and converts UI payload into optimizer inputs'],['Economics Layer','Calculates route value from composition, recovery and price assumptions'],['Optimization Engine','SciPy linprog solves objective subject to constraints'],['Post-processing','Calculates utilizations, curtailment, route ranking and economic comparison'],['API Response','Structured JSON results'],['Decision UI','KPIs, charts, route recommendations and caveat/interpretation']],
 dataapi:{input:'Scenario object/workbook containing feeds and composition, plant/fractionator capacities, recoveries, route connectivity and product prices.',endpoint:'POST /optimizer/run through /api/optimizer. The portfolio build can also load the bundled sample workbook.',response:'objective/baseline economics, uplift, allocations, feed usage, plant usage, fractionator loading and solver status.',storage:'Current portfolio scenario is file/in-memory based; production design should persist scenarios, assumptions and run results for traceability.'},
 validation:{works:['Capacity and availability constraints can be reconciled against returned allocations.','The solver returns a feasible optimal solution for the synthetic case.','The UI exposes the business assumptions instead of hiding them behind a single button.'],limits:['Linear yield/value assumptions simplify real gas-processing behavior.','No hydraulics, pressure, energy, product specification or dynamic operating constraints are represented.','Economic uplift is a synthetic demonstration, not claimed realized value.'],next:['Introduce nonlinear/surrogate process models where needed.','Add product-specification and energy/emissions constraints.','Connect live planning data and add scenario comparison / approval workflow.']}
},
'Visual Inspection':{
 deep:{summary:'A computer-vision/OCR pipeline that converts an equipment nameplate photograph into machine-readable text and a structured asset record for digital operator-round workflows.',facts:[['Input','JPG/PNG field image'],['Preparation','Pillow decoding + OpenCV grayscale/contrast/cleanup'],['Engine','EasyOCR text detection and recognition'],['Post-processing','Text lines mapped toward manufacturer/equipment fields'],['Serving','FastAPI POST /vision/nameplate'],['Frontend','Image preview, analyze action and structured OCR result'],['Best case','Straight-on, sharp, well-lit printed nameplates'],['Primary risk','Embossed, corroded, angled or low-contrast text']],details:['OCR combines text localization and recognition; preprocessing improves contrast and reduces image conditions that confuse the recognizer.','The current MVP is intentionally narrower than generic equipment classification because nameplate reading has a clearer operational workflow and measurable output.','A production solution would likely combine OCR with object detection, asset-master matching and confidence-based human review.','The API boundary allows the OCR engine to be replaced later without rebuilding the full application.']},
 build:[['1 · Use-case pivot','Moved away from a brittle generic equipment-classification dataset and selected nameplate digitization as a more business-relevant MVP.'],['2 · Image experiments','Tested industrial nameplate images and OpenCV preprocessing approaches.'],['3 · OCR engine','Integrated EasyOCR and direct byte decoding to handle browser uploads reliably.'],['4 · Structured service','Wrapped image handling and OCR in a FastAPI endpoint.'],['5 · Operator experience','Added image upload/preview, expected outputs, limitations and structured result display.'],['6 · Extensible design','Kept the vision engine modular so stronger OCR/VLM models can replace it later.']],
 cloud:[['Local prototype','Browser → localhost frontend → FastAPI :8003 → OpenCV/EasyOCR on the laptop CPU.'],['Container-ready','Vision dependencies and model runtime are packaged in a dedicated container because CV libraries differ from other services.'],['Azure application','Public frontend uploads image to a private vision API; Blob Storage can hold images temporarily if persistence/audit is required.'],['Production hardening','Add secure upload limits, malware/content controls, retention policy, GPU-enabled compute only if justified, monitoring and integration with the asset master/EAM system.']],
 architecture:[['Operator / Browser','Captures or uploads nameplate image'],['React Frontend','Shows preview and sends multipart image'],['FastAPI Application','Receives bytes and validates image'],['Image Processing','Pillow decode → OpenCV enhancement'],['OCR Engine','EasyOCR detects text regions and recognizes characters'],['Structuring Layer','Normalizes recognized text into useful asset fields'],['API Response','OCR/asset JSON with confidence where available'],['Workflow Output','Display, human verification and future asset-system integration']],
 dataapi:{input:'Multipart image upload: JPG/PNG, ideally clear printed text.',endpoint:'POST /vision/nameplate through /api/vision.',response:'Recognized OCR text and parsed equipment/nameplate fields produced by the vision engine.',storage:'No mandatory persistence in the MVP; production should define image retention/privacy and asset-record audit requirements.'},
 validation:{works:['Two industrial nameplate examples were used to test the full upload/decode/OCR path.','Printed manufacturer/equipment text is reasonably extractable when image quality is good.','Direct Pillow decoding resolved earlier browser-upload image handling issues.'],limits:['Faint embossed characters and difficult lighting remain unreliable.','OCR errors can create incorrect engineering data if automatically trusted.','The MVP does not yet match extracted identifiers against an authoritative asset registry.'],next:['Add OCR confidence and mandatory human confirmation below a threshold.','Use a modern multimodal/VLM extraction model as a benchmark or fallback.','Match serial/model/tag information to EAM/asset master and flag mismatches.']}
},
'Technology Intelligence':{
 deep:{summary:'A search-enabled GenAI research workflow designed to retrieve current external technology evidence, synthesize it into an executive brief and retain research history. The older keyword homepage scraper is retained only as a prototype artifact, not the preferred retrieval approach.',facts:[['Input','Natural-language research question with companies/themes/time window'],['Retrieval','LLM web-search/RAG capability rather than manual homepage scraping'],['Reasoning task','Find → filter → compare → synthesize'],['Source discipline','Prefer first-party company evidence and reputable industry/news sources'],['Serving','FastAPI research endpoint'],['Memory','Research history persisted for repeatability/comparison'],['Frontend','Prompt presets, free-form research, evidence/source display and history'],['Dependency','Live search requires an API model/account with search capability and available credits']],details:['The application should not compete with modern search-enabled foundation models at crawling the web. It should orchestrate those capabilities and add repeatability, structure and domain-specific synthesis.','A high-quality research prompt defines scope, recency, evidence standard and decision context.','The durable value of the module is not one answer; it is structured research history, comparisons over time, source discipline and eventually novelty/trend detection.','The current live-research path is only as strong as the configured search-capable API and must surface citations instead of presenting unsupported generated claims.']},
 build:[['1 · Initial collector','Built a company registry and HTML-link collector with keyword taxonomy. It proved the orchestration concept but returned too much evergreen/noisy content.'],['2 · Structured intelligence store','Added SQLite records, company/theme/maturity/significance fields and a FastAPI/dashboard layer.'],['3 · LLM attempt','Added OpenAI analysis, but API credit exhaustion exposed the distinction between ChatGPT subscription and API billing.'],['4 · Fallback logic','Rule-based analysis kept the prototype running but did not solve retrieval quality.'],['5 · Architectural correction','Reframed Module 4 around search/RAG-enabled model capabilities instead of custom homepage scraping.'],['6 · Product direction','Research question → web retrieval → evidence-backed synthesis → history → future novelty/trend comparison.']],
 cloud:[['Local prototype','React frontend → FastAPI :8004 → research API call + local SQLite.'],['Container-ready','Research service is isolated in a container; API credentials are injected as environment variables, never embedded in frontend code.'],['Azure application','Frontend is public. Research backend is private, uses Key Vault for secrets, and writes research history to a managed database instead of local SQLite.'],['Production hardening','Add rate/cost controls, observability, source/audit retention, scheduled research jobs, RBAC and safe outbound-network policies.']],
 architecture:[['User / Scheduler','Defines a research question or recurring intelligence brief'],['React Frontend','Collects scope and presents history/results'],['FastAPI Orchestrator','Builds validated research request and manages persistence'],['Search-enabled Model','Retrieves current web evidence and synthesizes findings'],['Source Layer','Primary company sources + trusted external evidence'],['Structuring / QA','Normalize findings, retain citations, score/compare where configured'],['Database','Research prompt, response, sources, timestamp and future structured developments'],['Executive UI','Brief, sources, history and future trend/novelty views']],
 dataapi:{input:'Natural-language research query; production schema can add company list, themes, time window, evidence preference and output format.',endpoint:'POST /research through /api/intelligence; GET /research/history for saved runs.',response:'Research brief plus source title/URL metadata; structured development objects are the recommended next evolution.',storage:'SQLite in the portfolio build; managed PostgreSQL/Azure SQL is the recommended cloud persistence layer.'},
 validation:{works:['The architectural weakness of homepage scraping has been identified and removed from the preferred design.','Frontend and API contract support prompt-based live research and saved history.','Sources are intended to remain visible with the synthesis rather than being hidden.'],limits:['Live quality depends on the search-enabled API/model and available API credits.','A one-shot brief is not yet a full autonomous intelligence agent with robust novelty detection.','SQLite/local history is not a production multi-user intelligence store.'],next:['Return typed JSON developments in addition to narrative brief.','Add deduplication/novelty against historical developments and weekly change detection.','Add scheduled research, cross-company benchmarking and executive trend radar.']}
}}

const guideTabs=[['Deep Dive',BookOpen],['Build Evolution',Milestone],['Cloud Evolution',Cloud],['Current Architecture',Network],['Data & API',Braces],['Validation & Limits',ShieldCheck]];
function ModuleKnowledge({name}){const[active,setActive]=useState('');const d=moduleDocs[name];if(!d)return null;return <div className="knowledgeDock"><div className="knowledgeBar"><div className="knowledgeLabel"><Info size={16}/><span>MODULE REFERENCE</span><small>Open any section for the technical story behind this application.</small></div><div className="knowledgeTabs">{guideTabs.map(([t,I])=><button key={t} className={active===t?'active':''} onClick={()=>setActive(active===t?'':t)}><I size={15}/>{t}<ChevronDown size={13} className={active===t?'chev open':'chev'}/></button>)}</div></div>{active&&<div className="knowledgePanel">{active==='Deep Dive'?<><div className="knowledgeLead"><span>TECHNICAL DEEP DIVE</span><h2>{name}: how the engine works</h2><p>{d.deep.summary}</p></div><div className="factGrid">{d.deep.facts.map(([k,v])=><div key={k}><span>{k}</span><b>{v}</b></div>)}</div><div className="detailGrid">{d.deep.details.map((x,i)=><div key={i}><b>{String(i+1).padStart(2,'0')}</b><p>{x}</p></div>)}</div></>:active==='Build Evolution'?<><div className="knowledgeLead"><span>ARCHITECTURE EVOLUTION</span><h2>How this module was built</h2><p>The evolution is shown deliberately so the portfolio explains not only the finished screen, but the engineering decisions that connected model development to an application.</p></div><div className="timeline">{d.build.map(([t,x],i)=><div className="timelineItem" key={t}><div className="timelineMarker">{i+1}</div><div><h3>{t}</h3><p>{x}</p></div></div>)}</div></>:active==='Cloud Evolution'?<><div className="knowledgeLead"><span>LOCAL → CLOUD</span><h2>How the deployment architecture evolves</h2><p>Dockerization and Azure do not change the business logic; they change where the components run, how they find each other, how state is persisted and how the application is secured and operated.</p></div><div className="evolutionGrid">{d.cloud.map(([t,x],i)=><div className="evolutionCard" key={t}><span>{String(i+1).padStart(2,'0')}</span><h3>{t}</h3><p>{x}</p>{i<d.cloud.length-1&&<ArrowRight className="evoArrow" size={20}/>}</div>)}</div></>:active==='Current Architecture'?<><div className="knowledgeLead"><span>CURRENT DATA FLOW</span><h2>End-to-end architecture schematic</h2><p>Follow one request from the user interface through integration, engine execution and back to the decision experience.</p></div><div className="archFlow">{d.architecture.map(([t,x],i)=><React.Fragment key={t}><div className="archBox"><span>{String(i+1).padStart(2,'0')}</span><b>{t}</b><small>{x}</small></div>{i<d.architecture.length-1&&<ArrowRight size={18} className="archArrow"/>}</React.Fragment>)}</div></>:active==='Data & API'?<><div className="knowledgeLead"><span>INTERFACES</span><h2>Data contract and API boundary</h2><p>This boundary is what allows the frontend, Python application and underlying engine to evolve independently.</p></div><div className="apiGrid"><div><span>INPUT CONTRACT</span><p>{d.dataapi.input}</p></div><div><span>API</span><p>{d.dataapi.endpoint}</p></div><div><span>RESPONSE</span><p>{d.dataapi.response}</p></div><div><span>STATE / STORAGE</span><p>{d.dataapi.storage}</p></div></div></>:<><div className="knowledgeLead"><span>ENGINEERING EVIDENCE</span><h2>What is proven, what is not, and what comes next</h2><p>A credible portfolio distinguishes implemented capability from assumptions and production work still required.</p></div><div className="validationGrid"><div><h3><CheckCircle2 size={18}/> What works now</h3>{d.validation.works.map(x=><p key={x}>✓ {x}</p>)}</div><div><h3><AlertTriangle size={18}/> Current limits</h3>{d.validation.limits.map(x=><p key={x}>• {x}</p>)}</div><div><h3><TrendingUp size={18}/> Production evolution</h3>{d.validation.next.map(x=><p key={x}>→ {x}</p>)}</div></div></>}</div>}</div>}

function Overview({setPage}){const cards=[['Compressor Health','Predict equipment degradation from multivariate operating data.'],['Feed Optimizer','Optimize constrained gas routing and quantify economic uplift.'],['Visual Inspection','Read equipment nameplates from field images using OCR.'],['Technology Intelligence','Research external AI and technology developments using live web evidence.']];return <>
 <section className="hero"><div className="eyebrow">AI OPERATIONS WORKBENCH</div><h1>Industrial AI that is<br/><em>understandable, usable and deployable.</em></h1><p className="lead">A portfolio-grade workbench showing how four different AI disciplines move from operational input to a decision, through APIs and into a production-style web experience.</p><div className="heroActions"><button className="primary" onClick={()=>setPage('Compressor Health')}>Explore the workbench <ArrowRight size={17}/></button><span className="quietBadge">4 modules · 1 architecture</span></div></section>
 <div className="sectionHead"><div><span className="eyebrow">CAPABILITIES</span><h2>Four problems. Four AI approaches.</h2></div></div>
 <div className="moduleGrid">{cards.map(([name,text])=>{let m=moduleMeta[name],Icon=m.icon;return <button className="moduleCard" key={name} onClick={()=>setPage(name)}><div className="moduleTop"><div className="moduleIcon"><Icon size={24}/></div><span>{m.tag}</span></div><h3>{name}</h3><p>{text}</p><div className="openLink">Open module <ArrowRight size={15}/></div></button>})}</div>
 <div className="architecture"><div><span className="eyebrow">END-TO-END ARCHITECTURE</span><h2>One interface, specialized engines.</h2><p>Users interact with a React web application. Each module calls a dedicated FastAPI service, which invokes the relevant Python engine, model or research workflow.</p></div><Flow steps={[{kicker:'EXPERIENCE',title:'React Web App',text:'Inputs, visuals, decisions'},{kicker:'INTEGRATION',title:'FastAPI',text:'Clean service contracts'},{kicker:'INTELLIGENCE',title:'AI Engines',text:'ML · OR · CV · GenAI'},{kicker:'DEPLOYMENT',title:'Cloud Ready',text:'Docker · Azure · HTTPS'}]}/></div>
 <section className="archPoster"><div className="sectionHead"><div><span className="eyebrow">REFERENCE VISUAL</span><h2>Representative architecture for all four modules</h2><p className="posterLead">This schematic is valid as the current representative design. The business flow, APIs, engines and data movement stay conceptually the same when moving to Azure; what changes in Azure is the hosting environment, networking, security, storage and operations tooling.</p></div></div><div className="posterWrap"><img src="/architecture-overview.png" alt="AI Operations Workbench architecture overview covering all modules and local-to-Azure evolution" className="posterImage"/><p className="architectureCaption">Representative architecture of the current Workbench. When the application is deployed to Azure, this visual will be updated to show the actual cloud-hosted architecture.</p></div></section>
 </>}

function CompressorPage(){const[file,setFile]=useState(null),[loading,setLoading]=useState(false),[error,setError]=useState(''),[result,setResult]=useState(null);
 async function analyze(f=file){if(!f)return setError('Choose a CSV file or use the sample case.');setLoading(true);setError('');setResult(null);let fd=new FormData();fd.append('file',f);try{let r=await fetch(api('compressor','/compressor/analyze'),{method:'POST',body:fd});let d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));setResult(d)}catch(e){setError(e.message)}finally{setLoading(false)}}
 async function sample(){try{let r=await fetch('/samples/compressor_C101_synthetic_6months.csv');let b=await r.blob();let f=new File([b],'compressor_C101_synthetic_6months.csv',{type:'text/csv'});setFile(f);analyze(f)}catch{setError('Could not load the sample dataset.')}}
 const status=result?.status||'Not analyzed';return <PageIntro name="Compressor Health"><ProblemCard problem="Rotating equipment can degrade gradually while individual tags still appear normal." decision="Is the current multivariable operating pattern normal, drifting or high-risk?" output="Health status, anomaly score, thresholds and a time trend."/>
 <div className="schemeCard"><div className="sectionMini"><span>EXAMPLE CASE</span><h2>Compressor C-101 health surveillance</h2><p>Six months of hourly operating data is converted into engineered features, scaled using the training baseline and scored by an Isolation Forest model.</p></div><Flow steps={[{kicker:'INPUT',title:'Sensor History',text:'Pressure · temperature · flow · speed · vibration'},{kicker:'PREPARE',title:'Feature Engineering',text:'Pressure ratio · ΔT · power/flow'},{kicker:'MODEL',title:'Isolation Forest',text:'Learn normal multivariate behavior'},{kicker:'DECISION',title:'Health Signal',text:'Normal · Attention · High'}]}/></div>
 <div className="workspace twoCol"><div className="panel"><div className="panelHead"><div><span className="eyebrow">INPUT</span><h2>Analyze operating history</h2></div><FileText size={22}/></div><p>Upload a CSV with the required compressor tags. For a quick demonstration, run the built-in synthetic C-101 case.</p><label className="dropzone"><UploadCloud size={27}/><b>{file?file.name:'Drop or choose compressor CSV'}</b><span>Hourly history · timestamp + operating variables</span><input type="file" accept=".csv" onChange={e=>setFile(e.target.files[0])}/></label><div className="buttonRow"><button className="primary" onClick={()=>analyze()} disabled={loading}>{loading?<RefreshCw size={16}/>:<Play size={16}/>} Analyze data</button><button className="secondary" onClick={sample}>Use sample case</button></div>{error&&<div className="error">{error}</div>}</div>
 <div className="decisionCard"><span className="eyebrow">DECISION OUTPUT</span><div className={'statusOrb '+String(status).toLowerCase().replace(' ','')}>{status}</div><h2>{result?'Current equipment condition':'Awaiting analysis'}</h2><p>{result?`The latest 24-hour smoothed anomaly score is ${fmt(result.current_anomaly_score)}.`:'Run the sample case or upload operating data to generate a health decision.'}</p>{result&&<div className="miniStats"><div><span>Rows analyzed</span><b>{result.rows_analyzed}</b></div><div><span>Attention threshold</span><b>{fmt(result.attention_threshold)}</b></div><div><span>High threshold</span><b>{fmt(result.high_threshold)}</b></div></div>}</div></div>
 {result&&<div className="panel resultPanel"><div className="panelHead"><div><span className="eyebrow">TREND</span><h2>Anomaly score over time</h2></div><LineIcon size={22}/></div><div className="bigChart"><ResponsiveContainer width="100%" height="100%"><LineChart data={result.trend}><CartesianGrid strokeDasharray="3 3" stroke="#26384c"/><XAxis dataKey="timestamp" tick={false}/><YAxis stroke="#8295ad"/><Tooltip/><ReferenceLine y={result.attention_threshold} stroke="#e7b35a" strokeDasharray="4 4"/><ReferenceLine y={result.high_threshold} stroke="#ef7272" strokeDasharray="4 4"/><Line type="monotone" dataKey="anomaly_score" stroke="#58dfc6" dot={false} strokeWidth={2}/></LineChart></ResponsiveContainer></div><div className="interpret"><ShieldCheck size={20}/><div><b>How to read this</b><span>The model does not predict a specific failure mode. It flags operating patterns that differ from the normal training baseline and therefore deserve engineering review.</span></div></div></div>}
 </PageIntro>}

function EditableTable({rows,setRows,columns}){const edit=(ri,key,val)=>setRows(rows.map((r,i)=>i===ri?{...r,[key]:columns.find(c=>c.key===key)?.numeric?Number(val):val}:r));return <div className="tablewrap"><table className="datatable"><thead><tr>{columns.map(c=><th key={c.key}>{c.label}</th>)}</tr></thead><tbody>{rows.map((r,ri)=><tr key={ri}>{columns.map(c=><td key={c.key}>{c.edit?<input type="number" step="any" value={r[c.key]??''} onChange={e=>edit(ri,c.key,e.target.value)}/>:String(r[c.key]??'')}</td>)}</tr>)}</tbody></table></div>}
function FeedPage(){const[scenario,setScenario]=useState(null),[base,setBase]=useState(null),[tab,setTab]=useState('feeds'),[loading,setLoading]=useState(true),[running,setRunning]=useState(false),[result,setResult]=useState(null),[error,setError]=useState(''),[upload,setUpload]=useState(null);
 const load=()=>{setLoading(true);fetch(api('optimizer','/optimizer/inputs')).then(r=>{if(!r.ok)throw Error('Optimizer API is not running.');return r.json()}).then(d=>{setScenario(d);setBase(structuredClone(d));setLoading(false)}).catch(e=>{setError(e.message);setLoading(false)})};useEffect(load,[]);
 const change=(key,rows)=>setScenario({...scenario,[key]:rows});async function run(){setRunning(true);setError('');setResult(null);try{let r=await fetch(api('optimizer','/optimizer/run'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(scenario)});let d=await r.json();if(!r.ok)throw Error(d.detail||'Optimization failed');setResult(d)}catch(e){setError(e.message)}finally{setRunning(false)}}
 async function runUpload(){if(!upload)return setError('Choose the optimizer workbook first.');let fd=new FormData();fd.append('file',upload);setRunning(true);setError('');try{let r=await fetch(api('optimizer','/optimizer/upload'),{method:'POST',body:fd});let d=await r.json();if(!r.ok)throw Error(d.detail||'Upload failed');setResult(d)}catch(e){setError(e.message)}finally{setRunning(false)}}
 const plantChart=useMemo(()=>{if(!result?.allocations||!scenario)return[];return scenario.plants.map(p=>({name:p.Plant_ID,used:result.allocations.filter(a=>a.plant===p.Plant_ID).reduce((s,a)=>s+a.flow_mmscfd,0),capacity:p.Max_Capacity_MMSCFD}))},[result,scenario]);
 if(loading)return <PageIntro name="Feed Optimizer"><div className="panel"><RefreshCw size={18}/> Loading scenario…</div></PageIntro>;
 return <PageIntro name="Feed Optimizer"><ProblemCard problem="Available gas streams differ in quantity and composition while processing and fractionation capacity is constrained." decision="How much of each feed should be routed through each feasible plant and fractionator?" output="A feasible allocation that maximizes synthetic daily product value and reveals bottlenecks."/>
 <div className="schemeCard"><div className="sectionMini"><span>EXAMPLE CASE</span><h2>Gas network allocation problem</h2><p>The optimizer chooses routes while respecting feed availability, plant capacities, allowed connections, NGL recovery and fractionation limits.</p></div><Flow steps={[{kicker:'SUPPLY',title:'Feed Streams',text:'Flow + composition'},{kicker:'PROCESS',title:'Gas Plants',text:'Capacity + recovery'},{kicker:'SEPARATE',title:'Fractionators',text:'NGL capacity + recovery'},{kicker:'VALUE',title:'Products',text:'C1 · C2 · C3 · C4 · C5+'}]}/></div>
 <div className="toolbar"><div><span className="smalllabel">SCENARIO</span><b> Base synthetic operating case</b></div><div className="toolactions"><button className="secondary" onClick={()=>{setScenario(structuredClone(base));setResult(null)}}><RotateCcw size={15}/> Reset sample</button><label className="secondary filebutton"><UploadCloud size={15}/> Upload Excel<input type="file" accept=".xlsx,.xls" onChange={e=>setUpload(e.target.files[0])}/></label>{upload&&<button className="secondary" onClick={runUpload}>Run uploaded workbook</button>}</div></div>
 <div className="inputgrid"><div className="inputmain"><div className="tabs"><button className={tab==='feeds'?'on':''} onClick={()=>setTab('feeds')}>1 · Feeds</button><button className={tab==='plants'?'on':''} onClick={()=>setTab('plants')}>2 · Capacity</button><button className={tab==='prices'?'on':''} onClick={()=>setTab('prices')}>3 · Economics</button></div><div className="inputcard">{tab==='feeds'&&<><div className="titleline"><div><h2>Feed inputs</h2><p>Edit available flow and composition. These are the raw materials the optimizer can route.</p></div><Database size={21}/></div><EditableTable rows={scenario.feeds} setRows={r=>change('feeds',r)} columns={[{key:'Feed_ID',label:'Feed'},{key:'Available_Flow_MMSCFD',label:'Flow MMSCFD',edit:1,numeric:1},{key:'C1_mol_pct',label:'C1 %',edit:1,numeric:1},{key:'C2_mol_pct',label:'C2 %',edit:1,numeric:1},{key:'C3_mol_pct',label:'C3 %',edit:1,numeric:1},{key:'C4_mol_pct',label:'C4 %',edit:1,numeric:1},{key:'C5plus_mol_pct',label:'C5+ %',edit:1,numeric:1},{key:'CO2_mol_pct',label:'CO2 %',edit:1,numeric:1},{key:'N2_mol_pct',label:'N2 %',edit:1,numeric:1}]}/></>}{tab==='plants'&&<><div className="titleline"><div><h2>Processing constraints</h2><p>Capacity and recovery values determine the feasible operating envelope.</p></div><Settings2 size={21}/></div><h3 className="subhead">Plants</h3><EditableTable rows={scenario.plants} setRows={r=>change('plants',r)} columns={[{key:'Plant_ID',label:'Plant'},{key:'Max_Capacity_MMSCFD',label:'Max capacity',edit:1,numeric:1},{key:'Min_Planned_Load_MMSCFD',label:'Min load',edit:1,numeric:1},{key:'Efficiency_Factor',label:'Efficiency',edit:1,numeric:1},{key:'Availability_Factor',label:'Availability',edit:1,numeric:1}]}/><h3 className="subhead">Fractionators</h3><EditableTable rows={scenario.fractionation} setRows={r=>change('fractionation',r)} columns={[{key:'Fractionator_ID',label:'Unit'},{key:'Max_NGL_kmol_per_day',label:'Max NGL kmol/day',edit:1,numeric:1},{key:'C2_Recovery',label:'C2 recovery',edit:1,numeric:1},{key:'C3_Recovery',label:'C3 recovery',edit:1,numeric:1},{key:'C4_Recovery',label:'C4 recovery',edit:1,numeric:1},{key:'C5plus_Recovery',label:'C5+ recovery',edit:1,numeric:1}]}/></>}{tab==='prices'&&<><div className="titleline"><div><h2>Economic assumptions</h2><p>Planning prices determine which feasible routes create the most value.</p></div><TrendingUp size={21}/></div><EditableTable rows={scenario.prices} setRows={r=>change('prices',r)} columns={[{key:'Component',label:'Component'},{key:'Product',label:'Product'},{key:'Planning_Price',label:'Planning price',edit:1,numeric:1},{key:'Price_Unit',label:'Unit'}]}/></>}</div></div>
 <aside className="runbox"><span className="eyebrow">OPTIMIZATION OBJECTIVE</span><h2>Maximize product value</h2><p>Linear programming evaluates feasible feed → plant → fractionator routes simultaneously instead of optimizing each asset independently.</p><div className="runmeta"><span>Decision variables</span><b>Route flow + curtailment</b><span>Constraints</span><b>Supply · plant · routing · fractionation</b><span>Engine</span><b>SciPy linear programming</b></div><button className="primary big" onClick={run} disabled={running}>{running?<RefreshCw size={17}/>:<Play size={17}/>} {running?'Optimizing…':'Run optimization'}</button></aside></div>{error&&<div className="error">{error}</div>}
 {result&&<div className="optimizerResults"><div className="sectionHead"><div><span className="eyebrow">RESULTS</span><h2>Recommended operating plan</h2></div><span className="successPill"><CheckCircle2 size={14}/> {result.status}</span></div><div className="kpis"><div><span>Baseline value</span><b>{money(result.baseline_daily_revenue)}</b><small>per day</small></div><div><span>Optimized value</span><b>{money(result.optimized_daily_revenue)}</b><small>per day</small></div><div className="accentkpi"><span>Value uplift</span><b>+{result.improvement_percent}%</b><small>{money(result.incremental_daily_value)} / day</small></div><div><span>Annualized uplift</span><b>{money(result.incremental_annual_value)}</b><small>synthetic illustration</small></div></div><div className="chartgrid"><div className="chartcard"><h3>Plant loading</h3><p>Optimized routed flow versus installed capacity.</p><div className="chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={plantChart}><CartesianGrid strokeDasharray="3 3" stroke="#26384c"/><XAxis dataKey="name" stroke="#879bb1"/><YAxis stroke="#879bb1"/><Tooltip/><Bar dataKey="used" fill="#58dfc6"/><Bar dataKey="capacity" fill="#344a60"/></BarChart></ResponsiveContainer></div></div><div className="chartcard"><h3>Recommended routes</h3><p>Highest-value non-zero allocations.</p><div className="routeList">{(result.allocations||[]).slice(0,8).map((a,i)=><div key={i}><span>{a.feed}</span><ArrowRight size={13}/><span>{a.plant}</span><ArrowRight size={13}/><span>{a.fractionator}</span><b>{fmt(a.flow_mmscfd)} MMSCFD</b></div>)}</div></div></div><div className="interpret"><AlertTriangle size={20}/><div><b>Portfolio note</b><span>All economics shown here are synthetic demonstration values. The point of the module is the decision workflow and constrained optimization architecture, not a claim of realized business value.</span></div></div></div>}
 </PageIntro>}

function VisionPage(){const[file,setFile]=useState(null),[preview,setPreview]=useState(''),[loading,setLoading]=useState(false),[error,setError]=useState(''),[result,setResult]=useState(null);function choose(f){setFile(f);setPreview(f?URL.createObjectURL(f):'');setResult(null)}async function analyze(){if(!file)return setError('Choose a JPG or PNG image first.');setLoading(true);setError('');let fd=new FormData();fd.append('file',file);try{let r=await fetch(api('vision','/vision/nameplate'),{method:'POST',body:fd});let d=await r.json();if(!r.ok)throw Error(d.detail||'Vision analysis failed');setResult(d)}catch(e){setError(e.message)}finally{setLoading(false)}}return <PageIntro name="Visual Inspection"><ProblemCard problem="Operators capture equipment information in the field, but nameplates and visual observations remain unstructured." decision="What equipment identity and text can be extracted reliably from the image?" output="OCR text and structured equipment information that can feed a digital operator-round workflow."/>
 <div className="schemeCard"><div className="sectionMini"><span>EXAMPLE CASE</span><h2>Equipment nameplate digitization</h2><p>A field photo is decoded, enhanced and passed through OCR so that useful asset information can be surfaced without manual transcription.</p></div><Flow steps={[{kicker:'CAPTURE',title:'Field Image',text:'Pump · compressor · motor nameplate'},{kicker:'PREPARE',title:'Image Enhancement',text:'Decode · contrast · cleanup'},{kicker:'AI',title:'OCR Engine',text:'Detect + recognize text'},{kicker:'OUTPUT',title:'Asset Record',text:'Manufacturer · model · ratings'}]}/></div>
 <div className="workspace twoCol"><div className="panel"><div className="panelHead"><div><span className="eyebrow">INPUT</span><h2>Upload equipment image</h2></div><Eye size={22}/></div><label className="dropzone imageDrop">{preview?<img src={preview}/>:<><ScanLine size={31}/><b>Choose a clear nameplate photo</b><span>Best results: straight-on, well lit, sharp printed text</span></>}<input type="file" accept="image/*" onChange={e=>choose(e.target.files[0])}/></label><button className="primary" onClick={analyze} disabled={loading}>{loading?<RefreshCw size={16}/>:<ScanLine size={16}/>} {loading?'Reading image…':'Read nameplate'}</button>{error&&<div className="error">{error}</div>}</div><div className="decisionCard"><span className="eyebrow">EXPECTED OUTPUT</span><h2>Structured field information</h2><p>The current MVP is strongest on clear printed nameplates. Embossed, dirty, angled or low-contrast text may need stronger image processing or a specialized vision model.</p><div className="capabilityList"><span><CheckCircle2/> Manufacturer / brand</span><span><CheckCircle2/> Equipment description</span><span><CheckCircle2/> Recognized text lines</span><span><AlertTriangle/> Faint embossed values may be unreliable</span></div></div></div>
 {result&&<div className="panel resultPanel"><div className="panelHead"><div><span className="eyebrow">VISION RESULT</span><h2>Extracted information</h2></div><CheckCircle2 size={22}/></div><pre className="jsonResult">{JSON.stringify(result,null,2)}</pre></div>}
 </PageIntro>}

function IntelligencePage(){const[query,setQuery]=useState(''),[loading,setLoading]=useState(false),[error,setError]=useState(''),[result,setResult]=useState(null),[history,setHistory]=useState([]);const presets=['Find the most significant AI, agentic AI, robotics and autonomous operations deployments by major oil & gas companies in the last 90 days. Prioritize deployed or scaling use cases over generic announcements.','Compare recent AI and autonomous operations developments at ADNOC, Aramco, Shell, BP, Chevron and ExxonMobil. Focus on operational relevance, maturity and evidence.','Identify technology developments in gas processing, predictive maintenance, optimization, digital twins and robotics that could be relevant to a gas operating company.'];
 function loadHistory(){fetch(api('intelligence','/research/history')).then(r=>r.ok?r.json():[]).then(setHistory).catch(()=>{})}useEffect(loadHistory,[]);async function research(){if(query.trim().length<12)return setError('Enter a more specific research question.');setLoading(true);setError('');setResult(null);try{let r=await fetch(api('intelligence','/research'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query})});let d=await r.json();if(!r.ok)throw Error(d.detail||'Research failed');setResult(d);loadHistory()}catch(e){setError(e.message)}finally{setLoading(false)}}
 return <PageIntro name="Technology Intelligence"><ProblemCard problem="Technology signals are scattered across company newsrooms, industry media and vendor announcements, creating noise and manual research effort." decision="What changed, how mature is it, and what is genuinely relevant to an operating company?" output="Evidence-backed research briefs with sources, implications and a searchable history of previous research."/>
 <div className="schemeCard"><div className="sectionMini"><span>DESIGNED APPROACH</span><h2>Search-enabled research, not homepage scraping</h2><p>Module 4 now uses a research prompt to search the live web, favor credible primary sources, synthesize findings, preserve citations and store the resulting brief.</p></div><Flow steps={[{kicker:'SCOPE',title:'Research Question',text:'Companies · themes · time window'},{kicker:'RETRIEVE',title:'Web Search / RAG',text:'Find relevant current evidence'},{kicker:'VERIFY',title:'Source Discipline',text:'Prefer first-party + trusted media'},{kicker:'SYNTHESIZE',title:'Executive Brief',text:'What changed · why it matters'}]}/></div>
 <div className="intelGrid"><div className="panel researchPanel"><div className="panelHead"><div><span className="eyebrow">LIVE RESEARCH</span><h2>Ask a decision-oriented question</h2></div><Search size={22}/></div><p>Use natural language. The best prompts specify the companies, technology themes, time window and what you want to compare.</p><div className="presetRow">{presets.map((p,i)=><button key={i} className="preset" onClick={()=>setQuery(p)}>Example {i+1}</button>)}</div><textarea className="researchBox" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Example: What are the most meaningful agentic AI and autonomous operations deployments by major oil & gas companies in the last 90 days, and what do they imply for a gas operator?"/><button className="primary" onClick={research} disabled={loading}>{loading?<RefreshCw size={16}/>:<Sparkles size={16}/>} {loading?'Researching the web…':'Run live research'}</button><div className="apiNote"><ShieldCheck size={17}/><span>Live research needs an OpenAI API key with available credits. The previous keyword scraper is no longer the primary research path.</span></div>{error&&<div className="error">{error}</div>}</div>
 <div className="panel historyPanel"><div className="panelHead"><div><span className="eyebrow">MEMORY</span><h2>Research history</h2></div><History size={22}/></div>{history.length?history.slice(0,6).map(h=><button className="historyItem" key={h.id} onClick={()=>{setQuery(h.query);setResult({report:h.report,sources:h.sources})}}><span>{new Date(h.created_at).toLocaleDateString()}</span><b>{h.query}</b></button>):<EmptyState title="No research runs yet" text="Completed research briefs will appear here."/>}</div></div>
 {result&&<div className="panel resultPanel intelResult"><div className="panelHead"><div><span className="eyebrow">RESEARCH BRIEF</span><h2>Evidence-backed synthesis</h2></div><FileText size={22}/></div><div className="reportText">{result.report}</div>{result.sources?.length>0&&<><h3>Sources</h3><div className="sourceList">{result.sources.map((s,i)=><a key={i} href={s.url} target="_blank" rel="noreferrer"><ExternalLink size={14}/><span>{s.title||s.url}</span></a>)}</div></>}</div>}
 </PageIntro>}

function App(){const[page,setPage]=useState('Overview');let body=page==='Overview'?<Overview setPage={setPage}/>:page==='Compressor Health'?<CompressorPage/>:page==='Feed Optimizer'?<FeedPage/>:page==='Visual Inspection'?<VisionPage/>:<IntelligencePage/>;return <div className="shell"><aside><div className="brand"><div className="brandMark">AI</div><div><b>OPERATIONS</b><span>WORKBENCH</span></div></div><div className="navLabel">WORKSPACE</div>{nav.map(([name,Icon])=><button key={name} className={'nav '+(page===name?'active':'')} onClick={()=>setPage(name)}><Icon size={18}/><span>{name}</span></button>)}<div className="sideFooter"><div className="liveDot"/><div><b>Portfolio Build</b><span>React + FastAPI + Python AI</span></div></div></aside><main><header><span>AI OPERATIONS WORKBENCH</span><div className="headerRight"><span className="versionBadge">PRODUCT EXPERIENCE</span><span className="localBadge"><i/>LOCAL DEVELOPMENT</span></div></header><div className="content">{body}</div></main></div>}
createRoot(document.getElementById('root')).render(<AppErrorBoundary><App/></AppErrorBoundary>);
